const currencyApiUrl = "https://open.er-api.com/v6/latest/INR";
const currenciesToShow = ["USD", "EUR", "GBP"];

// Format converted amount for display
function formatCurrency(amount, currencyCode) {
    return new Intl.NumberFormat("en-US", {
        style: "currency",
        currency: currencyCode,
        maximumFractionDigits: 0
    }).format(amount);
}

function incrementDuration(durationStr, daysToAdd) {
    const match = durationStr.match(/(\d+)\s*Days?\s*\/\s*(\d+)\s*Nights?/i);
    if (match) {
        const days = parseInt(match[1]) + daysToAdd;
        const nights = parseInt(match[2]) + daysToAdd;
        return `${days} Days / ${nights} Nights`;
    }
    return durationStr;
}

async function renderPackages(destName, destData) {
    const classicPrice = destData.price;
    const premiumPrice = Math.round(destData.price * 1.35);
    const elitePrice = Math.round(destData.price * 1.75);
    
    const classicDuration = destData.duration;
    const premiumDuration = incrementDuration(destData.duration, 1);
    const eliteDuration = incrementDuration(destData.duration, 2);
    
    const classicPlaces = destData.places.slice(0, 2);
    const premiumPlaces = destData.places;
    const elitePlaces = [...destData.places, "Private Guided Tour & VIP Access"];
    
    // Set destination title
    const headerTitle = document.getElementById("selection-title");
    if (headerTitle) {
        headerTitle.textContent = `Choose Your Package for ${destData.name}`;
    }
    
    let rates = null;
    try {
        const response = await fetch(currencyApiUrl);
        if (response.ok) {
            const data = await response.json();
            if (data.result === "success") {
                rates = data.rates;
            }
        }
    } catch (e) {
        console.error("Failed to load currency rates", e);
    }
    
    const getConversionHTML = (price) => {
        if (!rates) return '<span style="display: block;">Converting currency...</span>';
        return currenciesToShow.map(code => {
            const converted = price * rates[code];
            return `<span style="display: block;">&asymp; ${formatCurrency(converted, code)} ${code}</span>`;
        }).join("");
    };
    
    const container = document.getElementById("packages-container");
    if (!container) return;
    
    container.innerHTML = `
        <div class="packages-grid">
        <!-- Classic Package -->
        <div class="package-card classic">
            <span class="tier-badge">Classic</span>
            <h3>Classic Package</h3>
            <div class="price-section">
                <div class="price">₹${classicPrice.toLocaleString("en-IN")}</div>
                <div class="price-subtitle">per person</div>
                <div class="currency-conversion" id="classic-conv">
                    ${getConversionHTML(classicPrice)}
                </div>
            </div>
            <div class="details-section">
                <div class="detail-item">
                    <span class="icon">🕒</span>
                    <span><strong>Duration:</strong> ${classicDuration}</span>
                </div>
                <div class="detail-item">
                    <span class="icon">🛏</span>
                    <span><strong>Hotel Category:</strong> 3-Star Standard Hotel</span>
                </div>
                <div class="detail-item">
                    <span class="icon">🍽</span>
                    <span><strong>Meals Included:</strong> Breakfast Included</span>
                </div>
                <div class="detail-item places-covered">
                    <span class="places-title">📍 Places Covered:</span>
                    <ul>
                        ${classicPlaces.map(p => `<li>${p}</li>`).join("")}
                    </ul>
                </div>
            </div>
            <a href="booking.html?destination=${encodeURIComponent(destData.name)}&package=Classic" class="book-btn">Book Now</a>
        </div>

        <!-- Premium Package -->
        <div class="package-card premium">
            <h3>Premium Package</h3>
            <div class="price-section">
                <div class="price">₹${premiumPrice.toLocaleString("en-IN")}</div>
                <div class="price-subtitle">per person</div>
                <div class="currency-conversion" id="premium-conv">
                    ${getConversionHTML(premiumPrice)}
                </div>
            </div>
            <div class="details-section">
                <div class="detail-item">
                    <span class="icon">🕒</span>
                    <span><strong>Duration:</strong> ${premiumDuration}</span>
                </div>
                <div class="detail-item">
                    <span class="icon">🛏</span>
                    <span><strong>Hotel Category:</strong> 4-Star Premium Hotel</span>
                </div>
                <div class="detail-item">
                    <span class="icon">🍽</span>
                    <span><strong>Meals Included:</strong> Breakfast & Dinner Included</span>
                </div>
                <div class="detail-item places-covered">
                    <span class="places-title">📍 Places Covered:</span>
                    <ul>
                        ${premiumPlaces.map(p => `<li>${p}</li>`).join("")}
                    </ul>
                </div>
            </div>
            <a href="booking.html?destination=${encodeURIComponent(destData.name)}&package=Premium" class="book-btn">Book Now</a>
        </div>

        <!-- Elite Package -->
        <div class="package-card elite">
            <span class="tier-badge">Elite</span>
            <h3>Elite Package</h3>
            <div class="price-section">
                <div class="price">₹${elitePrice.toLocaleString("en-IN")}</div>
                <div class="price-subtitle">per person</div>
                <div class="currency-conversion" id="elite-conv">
                    ${getConversionHTML(elitePrice)}
                </div>
            </div>
            <div class="details-section">
                <div class="detail-item">
                    <span class="icon">🕒</span>
                    <span><strong>Duration:</strong> ${eliteDuration}</span>
                </div>
                <div class="detail-item">
                    <span class="icon">🛏</span>
                    <span><strong>Hotel Category:</strong> 5-Star Ultra Luxury Resort</span>
                </div>
                <div class="detail-item">
                    <span class="icon">🍽</span>
                    <span><strong>Meals Included:</strong> All Meals Included</span>
                </div>
                <div class="detail-item places-covered">
                    <span class="places-title">📍 Places Covered:</span>
                    <ul>
                        ${elitePlaces.map(p => `<li>${p}</li>`).join("")}
                    </ul>
                </div>
            </div>
            <a href="booking.html?destination=${encodeURIComponent(destData.name)}&package=Elite" class="book-btn">Book Now</a>
        </div>

</div>
    `;
}

// On load
window.addEventListener("DOMContentLoaded", () => {
    const params = new URLSearchParams(window.location.search);
    const destParam = params.get("destination");
    
    if (!destParam) {
        document.getElementById("packages-container").innerHTML = `<div class="error-msg">No destination selected. Please go back to <a href='trip.html'>Destinations</a>.</div>`;
        return;
    }
    
    const key = destParam.toLowerCase().replace(/\s+/g, "");
    const destData = destinationsData[key];
    
    if (!destData) {
        document.getElementById("packages-container").innerHTML = `<div class="error-msg">Destination "${destParam}" not found. Please go back to <a href='trip.html'>Destinations</a>.</div>`;
        return;
    }
    
    renderPackages(destParam, destData);
});
